// generatedQuery returns the SQL of a query generated by sqlc in metricsdb. The
// constants are unexported, so they are read from the sqlc output, which is the
// text the store executes.
func generatedQuery(t *testing.T, name string) string {
	t.Helper()
	src, err := os.ReadFile(filepath.Join("metricsdb", "metrics.sql.go"))
	if err != nil {
		t.Fatal(err)
	}
	start := "const " + name + " = `"
	body := string(src)
	i := strings.Index(body, start)
	if i < 0 {
		t.Fatalf("const %s not found in generated code", name)
	}
	body = body[i+len(start):]
	j := strings.Index(body, "`")
	if j < 0 {
		t.Fatalf("unterminated const %s", name)
	}
	return body[:j]
}

// explain returns the query plan lines of a statement with the given arguments.
func explain(t *testing.T, m *MetricsStore, sql string, args ...any) string {
	t.Helper()
	rows, err := m.db.reader.QueryContext(context.Background(), "EXPLAIN QUERY PLAN "+sql, args...)
	if err != nil {
		t.Fatalf("EXPLAIN QUERY PLAN: %v", err)
	}
	defer func() { _ = rows.Close() }()
	var plan []string
	for rows.Next() {
		var id, parent, notused int
		var detail string
		if err := rows.Scan(&id, &parent, &notused, &detail); err != nil {
			t.Fatal(err)
		}
		plan = append(plan, detail)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return strings.Join(plan, "\n")
}

// TestCompactSchemaPlans guards FA-UPT-06 and NFA-PERF-03 for the series-based
// tables: no statement may scan rollups, minutes or series, every retention
// statement is bounded by the primary key prefix series_id, and reads reach
// their rows through series lookups.
func TestCompactSchemaPlans(t *testing.T) {
	m := openMetrics(t, t.TempDir())
	cases := []struct {
		name  string
		sql   string
		args  []any
		want  []string // substrings the plan must contain
		avoid []string // substrings the plan must not contain
	}{
		{
			name:  "deleteRollupsOfSeriesBefore",
			sql:   generatedQuery(t, "deleteRollupsOfSeriesBefore"),
			args:  []any{int64(1), store.BucketHour, int64(1_000), int64(10)},
			want:  []string{"SEARCH rollups USING PRIMARY KEY (series_id=? AND bucket_ms=?"},
			avoid: []string{"SCAN rollups", "SCAN r"},
		},
		{
			name:  "deleteMinutesOfSeriesBefore",
			sql:   generatedQuery(t, "deleteMinutesOfSeriesBefore"),
			args:  []any{int64(1), int64(1_000), int64(10)},
			want:  []string{"SEARCH minutes USING PRIMARY KEY (series_id=?"},
			avoid: []string{"SCAN minutes", "SCAN m"},
		},
		{
			name:  "listSeriesIDsAfter",
			sql:   generatedQuery(t, "listSeriesIDsAfter"),
			args:  []any{int64(0), int64(256)},
			want:  []string{"SEARCH series USING INTEGER PRIMARY KEY"},
			avoid: []string{"SCAN series"},
		},
		{
			name:  "listRollups",
			sql:   generatedQuery(t, "listRollups"),
			args:  []any{"t", "m", int64(0), "", store.BucketHour, int64(0), int64(1 << 62)},
			want:  []string{"SEARCH r USING PRIMARY KEY (series_id=?", "SEARCH s USING COVERING INDEX"},
			avoid: []string{"SCAN rollups", "SCAN r", "SCAN s"},
		},
		{
			name:  "listRollupsBatch",
			sql:   generatedQuery(t, "listRollupsBatch"),
			args:  []any{"t", "", store.BucketHour, int64(0), int64(1 << 62), "m1", "m2"},
			want:  []string{"SEARCH r USING PRIMARY KEY (series_id=?", "SEARCH s USING COVERING INDEX"},
			avoid: []string{"SCAN rollups", "SCAN r", "SCAN s"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			sql := tc.sql
			if tc.name == "listRollupsBatch" {
				// sqlc leaves the slice as a marker; expand it to two placeholders.
				sql = strings.Replace(sql, "/*SLICE:monitor_ids*/?", "?,?", 1)
			}
			plan := explain(t, m, sql, tc.args...)
			t.Logf("plan:\n%s", plan)
			for _, w := range tc.want {
				if !strings.Contains(plan, w) {
					t.Errorf("plan lacks %q:\n%s", w, plan)
				}
			}
			for _, a := range tc.avoid {
				if strings.Contains(plan, a) {
					t.Errorf("plan contains %q:\n%s", a, plan)
				}
			}
		})
	}
}

// TestMigrationV3KeepsRows migrates a metrics.db at version 2 with rows in the
// old tables to version 3 and checks that every row arrived with identical
// values, latencies within 0.001 ms, and that the old tables are gone (ADR 0016).
func TestMigrationV3KeepsRows(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	path := filepath.Join(dir, MetricsFile)
	migrations, err := fs.Sub(metricsMigrationFiles, "migrations/metrics")
	if err != nil {
		t.Fatal(err)
	}

	// Version 2: the old schema with data, created by goose up to version 2.
	db, err := Open(ctx, Options{Path: path, Synchronous: SyncNormal, ReadConns: 1})
	if err != nil {
		t.Fatal(err)
	}
	provider, err := goose.NewProvider(goose.DialectSQLite3, db.writer, migrations)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := provider.UpTo(ctx, 2); err != nil {
		t.Fatalf("migrate to version 2: %v", err)
	}
	type rollupRow struct {
		tenant, monitor, node              string
		bucket, start, up, down, maint, un int64
		count                              int64
		avg, p95                           float64
	}
	type minuteRow struct {
		tenant, monitor, node          string
		minute, min, max, ok, errCount int64
		avg, p95                       float64
	}
	var rollups []rollupRow
	var minutes []minuteRow
	tx, err := db.writer.BeginTx(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, tenant := range []string{"t1", "t2"} {
		// The version 2 primary keys carry no tenant, so monitor IDs are unique
		// across tenants, as they are in practice.
		for _, mon := range []string{tenant + "-m1", tenant + "-m2"} {
			for _, node := range []string{"", "n1"} {
				for h := int64(0); h < 10; h++ {
					r := rollupRow{tenant, mon, node, store.BucketHour, h * store.BucketHour, 3000 + h, 100, 7, 3,
						h + 1, float64(h)*1.23456789 + 0.5, float64(h)*2.0009 + 0.0004}
					rollups = append(rollups, r)
					if _, err := tx.ExecContext(ctx, `INSERT INTO uptime_rollups (tenant_id, monitor_id, node_id, bucket_ms, start_ms,
						up_ms, down_ms, maint_ms, unknown_ms, latency_count, latency_avg, latency_p95)
						VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
						r.tenant, r.monitor, r.node, r.bucket, r.start, r.up, r.down, r.maint, r.un, r.count, r.avg, r.p95); err != nil {
						t.Fatal(err)
					}
				}
				for i := int64(0); i < 30; i++ {
					l := minuteRow{tenant, mon, node, 1_780_000_000_000 + i*60_000, 10 + i%7, 20 + i%13, 1 + i, i % 3,
						11.1111 + float64(i)*0.37, 17.7777 + float64(i)*0.11}
					minutes = append(minutes, l)
					if _, err := tx.ExecContext(ctx, `INSERT INTO latency_minutes (tenant_id, monitor_id, node_id, minute_ms,
						min_ms, max_ms, avg_ms, p95_ms, ok_count, err_count) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
						l.tenant, l.monitor, l.node, l.minute, l.min, l.max, l.avg, l.p95, l.ok, l.errCount); err != nil {
						t.Fatal(err)
					}
				}
			}
		}
	}
	if err := tx.Commit(); err != nil {
		t.Fatal(err)
	}
	if err := db.Close(); err != nil {
		t.Fatal(err)
	}

	// Version 3 runs on open.
	m, err := OpenMetrics(ctx, dir, MetricsOptions{})
	if err != nil {
		t.Fatalf("migrate to version 3: %v", err)
	}
	t.Cleanup(func() { _ = m.Close() })

	var old int
	if err := m.db.reader.QueryRowContext(ctx,
		`SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name IN ('uptime_rollups', 'latency_minutes')`).Scan(&old); err != nil {
		t.Fatal(err)
	}
	if old != 0 {
		t.Errorf("%d old tables remain", old)
	}

	// Rollups: integer fields identical, latencies within 0.001 ms.
	gotRollups, err := m.db.reader.QueryContext(ctx, `SELECT s.tenant_id, s.monitor_id, s.node_id, r.bucket_ms, r.start_ms,
		r.up_ms, r.down_ms, r.maint_ms, r.unknown_ms, r.latency_count, r.latency_avg_us, r.latency_p95_us
		FROM rollups AS r JOIN series AS s ON s.id = r.series_id`)
	if err != nil {
		t.Fatal(err)
	}
	migrated := 0
	for gotRollups.Next() {
		var tenant, mon, node string
		var bucket, start, up, down, maint, un, count, avgUs, p95Us int64
		if err := gotRollups.Scan(&tenant, &mon, &node, &bucket, &start, &up, &down, &maint, &un, &count, &avgUs, &p95Us); err != nil {
			t.Fatal(err)
		}
		migrated++
		// Compare with the row written at version 2.
		var want rollupRow
		for _, r := range rollups {
			if r.tenant == tenant && r.monitor == mon && r.node == node && r.bucket == bucket && r.start == start {
				want = r
			}
		}
		if want.tenant == "" || up != want.up || down != want.down || maint != want.maint || un != want.un || count != want.count {
			t.Errorf("rollup %s/%s/%s@%d: integers differ or row missing", tenant, mon, node, start)
		}
		checkMillis(t, "rollup avg", avgUs, want.avg)
		checkMillis(t, "rollup p95", p95Us, want.p95)
	}
	if err := gotRollups.Err(); err != nil {
		t.Fatal(err)
	}
	_ = gotRollups.Close()
	if migrated != len(rollups) {
		t.Errorf("rollups: %d migrated, want %d", migrated, len(rollups))
	}

	// Minutes.
	gotMinutes, err := m.db.reader.QueryContext(ctx, `SELECT s.tenant_id, s.monitor_id, s.node_id, mi.minute_ms, mi.min_ms,
		mi.max_ms, mi.avg_us, mi.p95_us, mi.ok_count, mi.err_count
		FROM minutes AS mi JOIN series AS s ON s.id = mi.series_id`)
	if err != nil {
		t.Fatal(err)
	}
	count := 0
	for gotMinutes.Next() {
		var tenant, mon, node string
		var minute, lo, hi, avgUs, p95Us, ok, errCount int64
		if err := gotMinutes.Scan(&tenant, &mon, &node, &minute, &lo, &hi, &avgUs, &p95Us, &ok, &errCount); err != nil {
			t.Fatal(err)
		}
		count++
		var want minuteRow
		for _, l := range minutes {
			if l.tenant == tenant && l.monitor == mon && l.node == node && l.minute == minute {
				want = l
			}
		}
		if want.tenant == "" || lo != want.min || hi != want.max || ok != want.ok || errCount != want.errCount {
			t.Errorf("minute %s/%s/%s@%d: integers differ or row missing", tenant, mon, node, minute)
		}
		checkMillis(t, "minute avg", avgUs, want.avg)
		checkMillis(t, "minute p95", p95Us, want.p95)
	}
	if err := gotMinutes.Err(); err != nil {
		t.Fatal(err)
	}
	_ = gotMinutes.Close()
	if count != len(minutes) {
		t.Errorf("minutes: %d migrated, want %d", count, len(minutes))
	}
	// Series: one per (tenant, monitor, node); m1 of t1 and t2 are distinct.
	var series int
	if err := m.db.reader.QueryRowContext(ctx, `SELECT COUNT(*) FROM series`).Scan(&series); err != nil {
		t.Fatal(err)
	}
	if series != 2*2*2 {
		t.Errorf("series = %d, want 8", series)
	}
}

// checkMillis compares a stored microsecond value with the original milliseconds.
func checkMillis(t *testing.T, what string, us int64, ms float64) {
	t.Helper()
	if d := float64(us)/1000 - ms; math.Abs(d) > 0.001 {
		t.Errorf("%s = %d us, want %.6f ms (diff %.6f)", what, us, ms, d)
	}
}

// TestMinuteRowSize measures the storage per latency minute (ADR 0016 estimates
// 40 to 50 bytes). It is a size check, not a benchmark: 10,000 minutes of
// 10 series are written, the file is vacuumed, and dbstat reads the pages of
// the minutes b-tree.
func TestMinuteRowSize(t *testing.T) {
	ctx := context.Background()
	m := openMetrics(t, t.TempDir())
	const series, perSeries = 10, 1000
	const start = int64(1_780_000_000_000)
	var minutes []store.LatencyMinute
	for s := range series {
		for i := range perSeries {
			lo := 10 + i%7
			minutes = append(minutes, store.LatencyMinute{
				TenantID: "tenant-a", MonitorID: fmt.Sprintf("monitor-%02d", s), NodeID: "n1",
				MinuteMs: start + int64(i)*60_000, Min: lo, Max: lo + i%13,
				Avg: float64(lo) + 0.123*float64(i%50), P95: float64(lo+i%13) + 0.5, OKCount: 1 + i%2, ErrCount: i % 3,
			})
		}
	}
	if err := m.CompactHeartbeats(ctx, minutes, nil); err != nil {
		t.Fatal(err)
	}
	if _, err := m.db.writer.ExecContext(ctx, "VACUUM"); err != nil {
		t.Fatal(err)
	}
	var rows int64
	if err := m.db.reader.QueryRowContext(ctx, "SELECT COUNT(*) FROM minutes").Scan(&rows); err != nil {
		t.Fatal(err)
	}
	var bytes int64
	if err := m.db.reader.QueryRowContext(ctx, "SELECT COALESCE(SUM(pgsize), 0) FROM dbstat WHERE name = 'minutes'").Scan(&bytes); err != nil {
		t.Fatalf("dbstat: %v", err)
	}
	if rows != series*perSeries {
		t.Fatalf("minutes = %d, want %d", rows, series*perSeries)
	}
	perRow := float64(bytes) / float64(rows)
	t.Logf("minutes: %d rows, %d bytes in pages (dbstat), %.1f bytes per row", rows, bytes, perRow)
	if perRow >= 80 {
		t.Errorf("%.1f bytes per minute row, want < 80", perRow)
	}
}

// TestMigrationV4InitialisesStreamPositions migrates a metrics.db at version 3
// with heartbeats of two streams to version 4 and checks that each stream's
// position is its highest stored seq. Down removes the table again.
func TestMigrationV4InitialisesStreamPositions(t *testing.T) {
	ctx := context.Background()
	migrations, err := fs.Sub(metricsMigrationFiles, "migrations/metrics")
	if err != nil {
		t.Fatal(err)
	}
	db, err := Open(ctx, Options{Path: filepath.Join(t.TempDir(), MetricsFile), Synchronous: SyncNormal, ReadConns: 1})
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = db.Close() }()
	provider, err := goose.NewProvider(goose.DialectSQLite3, db.writer, migrations)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := provider.UpTo(ctx, 3); err != nil {
		t.Fatalf("migrate to version 3: %v", err)
	}
	for _, hb := range []struct {
		node, inc string
		seq       int64
	}{
		{"n1", "inc-1", 1}, {"n1", "inc-1", 2}, {"n1", "inc-1", 5}, {"n1", "inc-2", 1}, {"n2", "inc-3", 9},
	} {
		if _, err := db.writer.ExecContext(ctx, `INSERT INTO heartbeats (node_id, incarnation, seq, tenant_id, monitor_id, ts_ms, status, latency_ms)
			VALUES (?, ?, ?, 't', 'm', 0, 0, 0)`, hb.node, hb.inc, hb.seq); err != nil {
			t.Fatal(err)
		}
	}

	if _, err := provider.UpTo(ctx, 4); err != nil {
		t.Fatalf("migrate to version 4: %v", err)
	}
	want := map[string]int64{"n1/inc-1": 5, "n1/inc-2": 1, "n2/inc-3": 9}
	rows, err := db.writer.QueryContext(ctx, `SELECT node_id, incarnation, seq FROM stream_positions`)
	if err != nil {
		t.Fatal(err)
	}
	got := map[string]int64{}
	for rows.Next() {
		var node, inc string
		var seq int64
		if err := rows.Scan(&node, &inc, &seq); err != nil {
			t.Fatal(err)
		}
		got[node+"/"+inc] = seq
	}
	if err := rows.Close(); err != nil {
		t.Fatal(err)
	}
	if fmt.Sprint(got) != fmt.Sprint(want) {
		t.Errorf("stream positions after migration = %v, want %v", got, want)
	}

	if _, err := provider.DownTo(ctx, 3); err != nil {
		t.Fatalf("migrate down to version 3: %v", err)
	}
	var tables int
	if err := db.writer.QueryRowContext(ctx, `SELECT COUNT(*) FROM sqlite_master WHERE name = 'stream_positions'`).Scan(&tables); err != nil {
		t.Fatal(err)
	}
	if tables != 0 {
		t.Errorf("stream_positions survived down migration")
	}
}
